#include <stdio.h>

int main(void)
{
    int x = 2;

    switch (x) {
    case 1:
        printf("jedna\n");
    case 2:
        printf("dva\n");
    case 3:
        printf("tri\n");
        break;
    default:
        printf("jine\n");
    }

    return 0;
}

#include <stdio.h>

int main(void)
{
    int i = 0;

    while (i++ < 3) {
        printf("%d ", i);
    }
    printf("| %d\n", i);

    return 0;
}
